#include <iostream>
#include <stdexcept>
#include <string>

int main() {
    int bolts{0};
    while (true) {
        std::cout << "How many bolts (1-10)? ";
        std::string text;
        if (!std::getline(std::cin, text)) {
            std::cout << "\nNo more input. Bye!\n";
            return 1;
        }
        try {
            bolts = std::stoi(text);
        } catch (const std::invalid_argument&) {
            std::cout << "  '" << text << "' is not a number.\n";
            continue;
        } catch (const std::out_of_range&) {
            std::cout << "  '" << text << "' is far too big.\n";
            continue;
        }
        if (bolts >= 1 && bolts <= 10) {
            break;
        }
        std::cout << "  " << bolts << " is not between 1 and 10.\n";
    }
    std::cout << "Ordering " << bolts << " bolts.\n";
}

