int cost_of(const std::string& row) {
    std::istringstream fields{row};
    std::string name, qty, cents;
    std::getline(fields, name, ',');
    std::getline(fields, qty, ',');
    std::getline(fields, cents, ',');
    return std::stoi(qty) * std::stoi(cents);
