        if (which == 4) throw std::runtime_error{"pump jammed"};
    } catch (const std::exception& e) {
        std::cout << which << ". what(): " << e.what() << '\n';
    }
}

int main() {
    for (int which = 1; which <= 4; ++which) {
        show(which);
    }
}

