#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

void trouble(int kind) {
    std::vector<int> v{1, 2, 3};
    if (kind == 1) {
        v.at(10) = 0;
    } else if (kind == 2) {
        std::stoi("abc");
    } else if (kind == 3) {
        throw std::runtime_error{"overheated"};
    }
}

void handle(int kind, const std::string& label) {
    try {
        trouble(kind);
        std::cout << label << " -> no handler runs\n";
    } catch (const std::out_of_range& e) {
        std::cout << label << " -> out_of_range handler\n";
    } catch (const std::invalid_argument& e) {
        std::cout << label << " -> invalid_argument handler\n";
    } catch (const std::exception& e) {
        std::cout << label << " -> exception handler\n";
    }
}

int main() {
    handle(0, "nothing thrown");
    handle(1, "v.at(10)");
    handle(2, "std::stoi(\"abc\")");
    handle(3, "throw runtime_error");
}

